// Task: level_1/task_12 | torch.diag(A) @ B
// Equivalent: out[i, j] = A[i] * B[i, j]
constexpr int kThreads = 256;
constexpr int kUnroll = 4;
template <typename scalar_t>
__global__ void diag_mul_rows_kernel(
const scalar_t* __restrict__ A,
const scalar_t* __restrict__ B,
scalar_t* __restrict__ Out,
int64_t N, int64_t M) {
const int64_t tid = blockIdx.x * blockDim.x + threadIdx.x;
const int64_t grid_stride = blockDim.x * gridDim.x;
const int64_t total = N * M;
for (int64_t base = tid; base < total;
base += grid_stride * kUnroll) {
#pragma unroll
for (int k = 0; k < kUnroll; ++k) {
int64_t idx = base + (int64_t)k * grid_stride;
if (idx < total) {
int64_t row = idx / M;
Out[idx] = A[row] * B[idx];
}
}
}
}
This kernel (which the system designed, implemented, tested for correctness, and bench-
marked) replaces PyTorch’s diag(A) @ B with a simple fused multiply, eliminating the
diagonal matrix materialization entirely.
